<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT * FROM users WHERE id=? AND department_id=? AND role='lecturer'");$q->execute([$id,$_SESSION['user']['department_id']]);$u=$q->fetch();if(!$u)redirect('/hod/lecturers/index.php');if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$sql='UPDATE users SET name=?,username=?,status=?'.(!empty($_POST['password'])?',password=?':'').' WHERE id=?';$v=[trim($_POST['name']),trim($_POST['username']),$_POST['status']];if(!empty($_POST['password']))$v[]=password_hash($_POST['password'],PASSWORD_DEFAULT);$v[]=$id;db()->prepare($sql)->execute($v);flash('Lecturer updated.');redirect('/hod/lecturers/index.php');}$title='Edit Lecturer';require __DIR__.'/../../includes/header.php';?><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" value="<?=e($u['name'])?>" required></label><label>Username<input name="username" value="<?=e($u['username'])?>" required></label><label>New Password <small>(leave blank to keep)</small><input type="password" name="password" minlength="6"></label><label>Status<select name="status"><option><?=$u['status']?></option><option value="<?= $u['status']==='active'?'inactive':'active' ?>"><?= $u['status']==='active'?'inactive':'active' ?></option></select></label><button>Update Lecturer</button></form></section><?php require __DIR__.'/../../includes/footer.php';?>
